    order by (lower(trim(coalesce(u.email,'')))=lower(trim(r->>'email'))) desc,
             i.created_at asc
    limit 1
  ) i on true;

  return jsonb_set(v_base,'{rows}',coalesce(v_rows,'[]'::jsonb),true)
         || jsonb_build_object('identity_version','127');
end;
$$;
